// Route104_MrBrineysHouse (zone 503): generated by converter/gen_interior_recipes_houses.py (Sapphire's simple people, signs
// and furniture messages). Messages: src/text/script/0375_room_Route104_MrBrineysHouse.txt
// Story (chapter Ch2, Sapphire data/maps/Route104_MrBrineysHouse/scripts.inc) after the "// ---- story" line:
// scripts 2-5 and 7, text lines 1-11. Mr. Briney (uid 1) and Peeko (uid 2): data/story/ch2.json (the zone's NPCs 0 and 1).
// Map scripts: 1007_..._init.s. Room origin (1,1): zone tile = Sapphire tile + (1,1).
#include "asm/field_script.inc"
#include "hoenn.h"
#include "hoenn_trainers.h"
#include "hoenn_key_items.h"
#include "hoenn_story.inc"

    ScriptEntry Script_1
    ScriptEntry BH_Briney           // 2: Route104_MrBrineysHouse_EventScript_15BCEB
    ScriptEntry BH_Peeko            // 3: Route104_MrBrineysHouse_EventScript_15BDD1
    ScriptEntry BH_Init             // 4: Route104_MrBrineysHouse_MapScript1_15BCB8 (zone init)
    ScriptEntry BH_ArriveByBoat     // 5: the end of DewfordTown_EventScript_SailToPetalburg (reserved by its warp)
    ScriptEntry BH_TestStart        // 6: HOENN_TEST_CH2=2 only (scenes/ch2_test.inc)
    ScriptEntry BH_StartChase       // 7: condition BH_CHASE 1 (1007_..._init.s): Briney chases Peeko around the table
    ScriptEntriesEnd

Script_1:
    ActorsPauseAll
    WordSetPlayerName 0
    SEPlay SEQ_SE_MESSAGE
    SystemMsg 0, 2
    LastKeyWait
    MsgWinCloseAll
    FinishAllEvents
    ActorsUnpauseAll
    VMHalt
// ---- story
#define BH_BRINEY_INDEX 0           // the zone's NPC list: Mr. Briney and Peeko are its only people (data/story/ch2.json)
#define BH_PEEKO_INDEX 1
#define BH_BRINEY_UID 1
#define BH_PEEKO_UID 2
// Sapphire's walk sequences after the rescue (setobjectmovementtype 1, 50 / 2, 51) as Black 2's walk-route move codes
// (ov036 ACTOR_MOVE_CODE_FUNCTION_TABLES 0x021cc990 -> route direction tables 0x021cbc70): 42 = down, left, up, right
// (route 35), 43 = left, up, right, down (route 36). Like Gen 3's MoveNextDirectionInSequence they walk on until the
// walk range (ch2.json areaw/areah 3 = Sapphire's movement range) ends, then turn; blocked = walk in place; the third
// leg ends level with the start (z for 42, x for 43, as Sapphire's _Step1); back at the start = from the top. So both go
// clockwise around the table (Sapphire (7-8,4-5)), Peeko three steps ahead of Mr. Briney.
#define BH_MOVE_CHASE_BRINEY 42
#define BH_MOVE_CHASE_PEEKO 43
// A move code can only change on a live actor (ActorSetMoveCode: script level 0, not in a zone init), so the zone init
// sets this map-local work (Black 2 clears 0x4000-0x401F at every zone init) and the condition runs script 7.
#define BH_CHASE 0x4000

BH_Init:
    h_setflag FLAG_LANDMARK_MR_BRINEY_HOUSE
    h_goto_if_ne VAR_BRINEY_HOUSE_STATE, 1, L_BH_InitPokenav
    h_setobjectxyperm BH_BRINEY_INDEX, 9 + 1, 3 + 1, 1  // setobjectxyperm 1, 9, 3
    h_setobjectxyperm BH_PEEKO_INDEX, 9 + 1, 6 + 1, 2   // setobjectxyperm 2, 9, 6
    WorkSetConst BH_CHASE, 1                            // setobjectmovementtype 1, 50 / 2, 51: script 7
L_BH_InitPokenav:
    h_goto_if_unset FLAG_RECEIVED_POKENAV, L_BH_InitDone
    h_setflag FLAG_HIDE_RIVAL_RUSTBORO
L_BH_InitDone:
    VMHalt

BH_Briney:
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_buffer_player
    h_goto_if_set FLAG_MR_BRINEY_SAILING_INTRO, L_BH_Again
    h_setflag FLAG_MR_BRINEY_SAILING_INTRO  // Route104_MrBrineysHouse_EventScript_15BD0E
    h_msgbox 1                      // Mr. Briney: Hold on, lass! Wait up, Peeko!
    h_yesno 2, HLIB_TMP             // Hm? You're {PLAYER}! ...So, you want to sail?
    h_goto_if_no HLIB_TMP, L_BH_DeclineDeliveries
    VMJump L_BH_SetSail
L_BH_Again:
    h_goto_if_unset FLAG_DELIVERED_STEVEN_LETTER, L_BH_LetterAndPackage
    h_goto_if_unset FLAG_DELIVERED_DEVON_GOODS, L_BH_Package
    ParentActorMsg MSGFILE_SCRIPT, 7, 0, 0  // Mr. Briney: Ahoy! For you, I'll go out to sea anytime!...
    ListMenu_AnchorTopRight 31, 8, 0, 1, HLIB_TMP   // multichoicedefault 21, 8, 14 (DEWFORD / CANCEL), 1, 0
    ListMenuAdd 10, 65535, 0
    ListMenuAdd 11, 65535, 1
    ListMenuShow
    h_goto_if_eq HLIB_TMP, 0, L_BH_SetSail
    h_msgbox 8                      // Mr. Briney: Is that so? Well, Peeko owes her life to you...
    h_release
L_BH_LetterAndPackage:              // Route104_MrBrineysHouse_EventScript_15BD65
    h_yesno 5, HLIB_TMP
    h_goto_if_no HLIB_TMP, L_BH_DeclineDeliveries
    VMJump L_BH_SetSail
L_BH_Package:                       // Route104_MrBrineysHouse_EventScript_15BD7E
    h_yesno 6, HLIB_TMP
    h_goto_if_no HLIB_TMP, L_BH_DeclineDeliveries
    VMJump L_BH_SetSail
L_BH_DeclineDeliveries:             // Route104_MrBrineysHouse_EventScript_15BD97
    h_msgbox 4                      // Mr. Briney: Is that so? Your deliveries can wait?...
    h_release

// Route104_MrBrineysHouse_EventScript_15BDAB. EventScript_BackupMrBrineyLocation (VAR_BRINEY_LOCATION -> 0x8008, 0
// while at sea; Route 104 copies it back on landing) is left out: Black 2's boat trip is one uninterrupted scene, so
// VAR_BRINEY_LOCATION keeps its value, the same as Sapphire's after the trip (and 0x8008 does not survive a warp).
L_BH_SetSail:
    h_msgbox 3                      // Mr. Briney: Dewford, here we come! Anchors aweigh! ...
    h_closemessage
    h_setvar VAR_BOARD_BRINEY_BOAT_ROUTE104_STATE, 1
    h_clearflag FLAG_HIDE_MR_BRINEY_ROUTE104
    h_setflag FLAG_HIDE_MR_BRINEY_ROUTE104_HOUSE
    h_setflag FLAG_HIDE_PEEKO_BRINEY_HOUSE
    // warp MAP_ROUTE104, 255, 13, 51: Route 104 (zone 329) runs its boat scene (script 4, scenes/Route104_ch2.inc)
    h_warp_scene 329, 13 + 48, 51 + 240, 2, 4
    h_release

BH_ArriveByBoat:                    // the crossing from Dewford ends here (scenes/DewfordTown.inc, ch2_sail)
    h_lock
    FadeInBlack
    FadeWait
    h_release

BH_TestStart:
#ifdef HOENN_TEST_CH2
    h_lock
    VMCall Sub_Ch2TestStart
    h_release
#include "scenes/ch2_test.inc"
#endif
    VMHalt

// Route104_MrBrineysHouse_EventScript_15BCD4's movement types, once the actors exist (only those the hide flags show)
BH_StartChase:
    WorkSetConst BH_CHASE, 0
    h_goto_if_set FLAG_HIDE_MR_BRINEY_ROUTE104_HOUSE, L_BH_ChasePeeko
    ActorSetMoveCode BH_BRINEY_UID, BH_MOVE_CHASE_BRINEY
L_BH_ChasePeeko:
    h_goto_if_set FLAG_HIDE_PEEKO_BRINEY_HOUSE, L_BH_ChaseDone
    ActorSetMoveCode BH_PEEKO_UID, BH_MOVE_CHASE_PEEKO
L_BH_ChaseDone:
    VMHalt

BH_Peeko:
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_waitse
    h_playmoncry SPECIES_WINGULL
    h_msgbox 9                      // Peeko: Pii pihyoroo!
    h_waitmoncry
    h_release
    .balign 4, 0
